package shop

import "fmt"

// Cart holds items and their prices in cents.
type Cart struct {
	items map[string]int
}

// Add adds qty items at price cents each.
func (c *Cart) Add(item string, qty, price int) {
	if c.items == nil {
		c.items = map[string]int{}
	}
	c.items[item] += qty * price
}

// Total is the cart's total in cents.
func (c *Cart) Total() int {
	total := 0
	for _, cents := range c.items {
		total += cents
	}
	return total
}

// Receipt is the total as text.
func (c *Cart) Receipt() string {
	return "Total: " + formatCents(c.Total())
}

func formatCents(cents int) string {
	return fmt.Sprintf("$%d.%d", cents/100, cents%100)
}

