import { test } from 'node:test';
import assert from 'node:assert/strict';
import { dedupe } from '../src/dedupe.js';

test('dedupes by key, keeping the first in order', () => {
  const people = [{ id: 2, n: 'a' }, { id: 1, n: 'b' }, { id: 2, n: 'c' }];
  assert.deepEqual(dedupe(people, p => p.id), [{ id: 2, n: 'a' }, { id: 1, n: 'b' }]);
  assert.deepEqual(dedupe(['A', 'a', 'b'], s => s.toLowerCase()), ['A', 'b']);
  assert.deepEqual(dedupe([3, 3, 1]), [3, 1]);
  assert.deepEqual(dedupe([]), []);
});

